package server.bots;
import client.Character;import client.Job;import server.life.Monster;import server.maps.MapleMap;import scripting.event.EventInstanceManager;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class BotPinkBeanStrategyTest {
 private Character bot(int wave,Job job){var b=mock(Character.class);var map=mock(MapleMap.class);var event=mock(EventInstanceManager.class);when(b.getMap()).thenReturn(map);when(b.getMapId()).thenReturn(270050100);when(b.getEventInstance()).thenReturn(event);when(event.getName()).thenReturn("PinkBean1");when(event.getIntProperty("stage")).thenReturn(wave);when(b.getJob()).thenReturn(job);return b;}
 private Monster mob(Character b,int id){var m=mock(Monster.class);when(m.getId()).thenReturn(id);when(m.isAlive()).thenReturn(true);when(b.getMap().getMonsterById(id)).thenReturn(m);return m;}
 @Test void waveThreeChoosesSolomonBeforeHuginAndRex(){var b=bot(3,Job.NIGHTLORD);var s=mob(b,8820003);var h=mob(b,8820005);var r=mob(b,8820004);assertEquals(List.of(s),BotPinkBeanStrategy.targets(b,List.of(r,h,s)));when(b.getMap().getMonsterById(8820003)).thenReturn(null);assertEquals(List.of(h),BotPinkBeanStrategy.targets(b,List.of(r,h)));}
 @Test void reflectingPreferredStatueDoesNotSendTheCrewChasingRex(){var b=bot(3,Job.NIGHTLORD);mob(b,8820003);var r=mob(b,8820004);assertTrue(BotPinkBeanStrategy.targets(b,List.of(r)).isEmpty());}
 @Test void meleeLeavesMuninToRangedAndWaitsWhenOnlyMuninRemains(){var b=bot(4,Job.HERO);var m=mob(b,8820006);assertTrue(BotPinkBeanStrategy.targets(b,List.of(m)).isEmpty());}
 @Test void secondPartyWorksTheRightSideFirst(){var b=bot(4,Job.BOWMASTER);var s=mob(b,8820003);var r=mob(b,8820004);var c=new BotPinkBeanRun.Crew();for(int i=0;i<5;i++)c.bots.add(mock(Character.class));c.bots.add(b);try(var crews=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS)){crews.when(()->BotPinkBeanRun.crew(b)).thenReturn(c);assertEquals(List.of(r),BotPinkBeanStrategy.targets(b,List.of(s,r)));}}
 @Test void normalAddsRemainEligibleAndOtherEncountersAreUnchanged(){var b=bot(3,Job.BISHOP);var s=mob(b,8820003);var add=mob(b,8820007);assertEquals(List.of(s,add),BotPinkBeanStrategy.targets(b,List.of(s,add)));when(b.getMapId()).thenReturn(240060200);var original=List.of(s,add);assertSame(original,BotPinkBeanStrategy.targets(b,original));}
 @Test void meleeWaitsForMuninRatherThanStartingArielEarly(){var b=bot(5,Job.HERO);var m=mob(b,8820006);var a=mob(b,8820002);assertTrue(BotPinkBeanStrategy.targets(b,List.of(m,a)).isEmpty());when(b.getMap().getMonsterById(8820006)).thenReturn(null);assertEquals(List.of(a),BotPinkBeanStrategy.targets(b,List.of(a)));}

 @Test void attackingSummonsWaitForTheBodyButBeholderRemainsAvailable(){var b=bot(3,Job.BISHOP);assertFalse(BotPinkBeanSummons.allowed(b,constants.skills.Bishop.BAHAMUT));assertFalse(BotPinkBeanSummons.allowed(b,constants.skills.Bowmaster.PHOENIX));assertTrue(BotPinkBeanSummons.allowed(b,constants.skills.DarkKnight.BEHOLDER));mob(b,8820001);assertTrue(BotPinkBeanSummons.allowed(b,constants.skills.Bishop.BAHAMUT));when(b.getMapId()).thenReturn(240060200);assertTrue(BotPinkBeanSummons.allowed(b,constants.skills.Bowmaster.PHOENIX));}
 @Test void anExistingStatuePhaseSummonIsActuallyCancelledThroughTheNativeBuffPath(){var b=bot(3,Job.BISHOP);when(b.isAlive()).thenReturn(true);var summon=mock(server.maps.Summon.class);when(summon.getSkill()).thenReturn(constants.skills.Bishop.BAHAMUT);when(summon.getSkillLevel()).thenReturn((byte)30);when(b.getSummonsValues()).thenReturn(List.of(summon));var skill=mock(client.Skill.class);var fx=mock(server.StatEffect.class);when(skill.getEffect(30)).thenReturn(fx);try(var skills=mockStatic(client.SkillFactory.class)){skills.when(()->client.SkillFactory.getSkill(constants.skills.Bishop.BAHAMUT)).thenReturn(skill);BotSummonCombat.tick(new BotEntry(b,b,null),b);verify(b).cancelEffect(fx,false,-1);}}

 @Test void anAoePlanThatWouldWakeTheBirdIsRejectedRatherThanLosingItsCollateral()throws Exception{
  var b=bot(3,Job.DARKKNIGHT);var s=mob(b,8820003);var h=mob(b,8820005);var plan=new BotCombatManager.AttackPlan(0,0,1,new java.awt.Rectangle(),List.of(s,h),BotCombatManager.AttackRoute.CLOSE,0,0,0,0,0,0,1000,client.inventory.WeaponType.SPEAR_STAB);
  var choose=BotCombatManager.class.getDeclaredMethod("selectBestAttackPlan",BotEntry.class,Character.class,List.class);choose.setAccessible(true);assertNull(choose.invoke(null,new BotEntry(b,b,null),b,List.of(plan)));assertEquals(List.of(s,h),plan.targets);
 }

 @Test void rightPartyMeleeDoesNotAbandonItsRangedSupportDuringMunin(){var b=bot(4,Job.DARKKNIGHT);var s=mob(b,8820003);var m=mob(b,8820006);var c=new BotPinkBeanRun.Crew();for(int i=0;i<5;i++)c.bots.add(mock(Character.class));c.bots.add(b);try(var crews=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS)){crews.when(()->BotPinkBeanRun.crew(b)).thenReturn(c);assertTrue(BotPinkBeanStrategy.targets(b,List.of(s,m)).isEmpty());when(b.getMap().getMonsterById(8820006)).thenReturn(null);assertEquals(List.of(s),BotPinkBeanStrategy.targets(b,List.of(s)));}}

 @Test void waveWarningMovesInnerPlatformOccupantsBeforeTheBirdExistsAndAcceptsNormalArrival(){assertEquals(new java.awt.Point(540,-102),BotPinkBeanPlatforms.adjustment(new java.awt.Point(403,-102),4));assertEquals(new java.awt.Point(-530,-99),BotPinkBeanPlatforms.adjustment(new java.awt.Point(-413,-99),3));assertNull(BotPinkBeanPlatforms.adjustment(new java.awt.Point(536,-102),4));assertNull(BotPinkBeanPlatforms.adjustment(new java.awt.Point(-526,-99),3));assertNull(BotPinkBeanPlatforms.adjustment(new java.awt.Point(403,-102),3));assertNull(BotPinkBeanPlatforms.adjustment(new java.awt.Point(403,-42),4));}

 @Test void onlyTheOppositePartyStagesOnceTheLastStatueIsLow(){var b=bot(4,Job.NIGHTLORD);var h=mob(b,8820005);when(h.getMaxHp()).thenReturn(450000000);when(h.getHp()).thenReturn(40000000);when(b.getMap().getAllMonsters()).thenReturn(List.of(h));var c=new BotPinkBeanRun.Crew();for(int i=0;i<5;i++)c.bots.add(mock(Character.class));c.bots.add(b);try(var crews=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS)){crews.when(()->BotPinkBeanRun.crew(b)).thenReturn(c);assertEquals(new java.awt.Point(900,-42),BotPinkBeanTransition.destination(b));when(h.getHp()).thenReturn(200000000);assertNull(BotPinkBeanTransition.destination(b));when(h.getHp()).thenReturn(40000000);var r=mob(b,8820004);when(b.getMap().getAllMonsters()).thenReturn(List.of(h,r));assertNull(BotPinkBeanTransition.destination(b));when(b.getMap().getAllMonsters()).thenReturn(List.of(h));c.bots.remove(b);while(c.bots.size()<11)c.bots.add(mock(Character.class));c.bots.add(b);assertNull(BotPinkBeanTransition.destination(b));}}

 @Test void nativeWarningStagesBeforeStatuesAppearButDoesNotBlockTheRealBody(){var b=bot(3,Job.NIGHTLORD);when(b.getMap().getAllMonsters()).thenReturn(List.of());var c=new BotPinkBeanRun.Crew();for(int i=0;i<5;i++)c.bots.add(mock(Character.class));c.bots.add(b);try(var crews=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS)){crews.when(()->BotPinkBeanRun.crew(b)).thenReturn(c);assertEquals(new java.awt.Point(-830,-42),BotPinkBeanTransition.destination(b));when(b.getEventInstance().getIntProperty("stage")).thenReturn(4);assertEquals(new java.awt.Point(840,-42),BotPinkBeanTransition.destination(b));when(b.getEventInstance().getIntProperty("stage")).thenReturn(5);assertEquals(new java.awt.Point(840,-42),BotPinkBeanTransition.destination(b));mob(b,8820001);assertNull(BotPinkBeanTransition.destination(b));}}

 @Test void waveFourLeftPartiesWorkSolomonWhileRightMeleeWaitsForMunin(){
  var ranged=bot(4,Job.NIGHTLORD);var sol=mob(ranged,8820003);var rex=mob(ranged,8820004);var munin=mob(ranged,8820006);assertEquals(List.of(sol),BotPinkBeanStrategy.targets(ranged,List.of(sol,rex,munin)));
  var melee=bot(4,Job.HERO);var left=mob(melee,8820003);var bird=mob(melee,8820006);assertEquals(List.of(left),BotPinkBeanStrategy.targets(melee,List.of(left,bird)));
 }
 @Test void waveThreeKeepsAllPartiesOnSolomonThenHuginBeforeRex(){
  var b=bot(3,Job.DARKKNIGHT);var sol=mob(b,8820003);var rex=mob(b,8820004);var h=mob(b,8820005);var c=new BotPinkBeanRun.Crew();c.bots.add(b);
  try(var run=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS)){run.when(()->BotPinkBeanRun.crew(b)).thenReturn(c);assertEquals(List.of(sol),BotPinkBeanStrategy.targets(b,List.of(sol,h,rex)));when(b.getMap().getMonsterById(8820003)).thenReturn(null);assertEquals(List.of(h),BotPinkBeanStrategy.targets(b,List.of(h,rex)));}
 }
 @Test void leftPartyStagesOnItsAssignedSideBeforeMuninAppears(){var b=bot(3,Job.NIGHTLORD);var rex=mob(b,8820004);when(rex.getMaxHp()).thenReturn(300000000);when(rex.getHp()).thenReturn(20000000);when(b.getMap().getAllMonsters()).thenReturn(List.of(rex));var c=new BotPinkBeanRun.Crew();for(int i=0;i<11;i++)c.bots.add(mock(Character.class));c.bots.add(b);try(var crews=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS)){crews.when(()->BotPinkBeanRun.crew(b)).thenReturn(c);assertEquals(new java.awt.Point(-900,-42),BotPinkBeanTransition.destination(b));}}
 @Test void theWaveFourWarningDoesNotSendLeftPartiesBackAcrossMuninsSpawn(){var b=bot(4,Job.BISHOP);when(b.getMap().getAllMonsters()).thenReturn(List.of());var crew=new BotPinkBeanRun.Crew();for(int i=0;i<11;i++)crew.bots.add(mock(Character.class));crew.bots.add(b);try(var run=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS)){run.when(()->BotPinkBeanRun.crew(b)).thenReturn(crew);assertFalse(BotPinkBeanRun.rightSide(crew,b));assertEquals(new java.awt.Point(-830,-42),BotPinkBeanTransition.destination(b));when(b.getEventInstance().getIntProperty("stage")).thenReturn(2);assertEquals(new java.awt.Point(-830,-42),BotPinkBeanTransition.destination(b));}}
 @Test void postArielReactorDelayMustKeepTheCompletedBodyRallyOnTheRight(){
  var b=bot(5,Job.NIGHTLORD);when(b.getMap().getAllMonsters()).thenReturn(List.of());var c=new BotPinkBeanRun.Crew();c.bots.add(b);c.notices.add("body-rally");c.notices.add("body-rally-ready");
  try(var run=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS)){run.when(()->BotPinkBeanRun.crew(b)).thenReturn(c);assertEquals(new java.awt.Point(840,-42),BotPinkBeanTransition.destination(b));mob(b,8820001);assertNull(BotPinkBeanTransition.destination(b));}
 }
}
